// Somme maximale d'un sous-tableau contigu (algorithme de Kadane).
export function maxSubarray(nums) {
  // BUG : initialise à 0 — faux quand tous les nombres sont négatifs.
  let best = 0, cur = 0;
  for (const n of nums) { cur = Math.max(0, cur + n); best = Math.max(best, cur); }
  return best;
}

